replacements.before:
// A trailing half-group must fail without losing earlier
// complete groups still waiting in a large decode batch.
if (multiframe) flush_pending_frames();
throw std::runtime_error("LLR input ended before a complete DTMB FEC frame");

replacements.after:
// A finite IQ recording may end between FEC group boundaries.
// Keep every complete, validated group; never pad missing LLRs.
// An incomplete float is a corrupt private pipe, not a tail.
if (input.bad() || bytes_read % sizeof(float) != 0) {
    throw std::runtime_error("invalid trailing LLR input bytes");
}
const auto trailing_llrs = static_cast<std::size_t>(bytes_read) / sizeof(float);
if (!std::all_of(transmitted_llr.begin(), transmitted_llr.begin() + trailing_llrs,
                 [](float value) { return std::isfinite(value); })) {
    throw std::runtime_error("LLR input contains a nonfinite value");
}
flush_pending_frames();
std::cerr << "trailing_fec_llrs=" << trailing_llrs << '\n';
break;
